#!/bin/sh
# SPDX-License-Identifier: 0BSD
# Copyright (c) 2026 Bjorn Pagen
# The Idris side's vocabulary of the upstream dialects Emit writes, as
# the specification lists them, generated by idris-mlir-tblgen: two
# modules per dialect from the admitted record file the dialect's Idris
# specification writes for it
# (foreign/idr/include/idr/IR/Generated/IdrAdmitted<Name>.td, which
# includes upstream's ODS of the dialect's ops and holds one record per op
# the specification admits), its syntax,
# compiler/src/IdrisMLIR/Syntax/<Name>.idr (-gen-idris-syntax: the enums
# its admitted ops, types and attributes take, and its types and
# attributes, which IdrisMLIR.MLIR's types and attributes hold), and its
# ops, compiler/src/IdrisMLIR/Dialect/<Name>.idr (-gen-idris-dialect: the
# builder of each admitted op the frontend writes, with the guards its
# record gives it, over its syntax); and, for a dialect whose types and
# attributes the bytecode writer encodes, its entries,
# compiler/src/IdrisMLIR/Encoding/<Name>.idr (-gen-idris-bytecode: the code
# and the parts of each record the frontend writes), from the entries file
# the specification writes for it (Idr<Name>Entries.td beside the admitted
# record file, which includes the dialect's bytecode records, the ones
# mlir-tblgen -gen-bytecode reads for its C++ reader, and holds one record
# per entry the frontend writes). Which ops, types and attributes a dialect's modules
# hold is the specification's, read from its records, so upstream's ODS
# given alone would leave them none. The idr dialect's own
# modules are not these: the dialect's Idris specification writes them
# with the rest of its outputs, and its manifest
# (foreign/idr/generated.manifest) holds them.
#
#     tools/dialects.sh generate   write each module that changed (make build)
#     tools/dialects.sh check      say whether each module is current
#
# With `typecheck` after either, the generator is make typecheck's
# idris-mlir-tblgen, and MLIR's ODS is that of the patched tree its
# bootstrap step reads (tools/bootstrap.sh typecheck), with the ODS that
# step's build generates, where stage 2 is not built. The records, and so
# the modules, are stage 2's only while that step's last build is of the
# pinned tree. `make typecheck` runs the step first, so it rebuilds a tree
# the pin has moved past; this script run alone reads the tree the step
# built last, and writes the old pin's module wherever upstream's ODS has
# changed since.
#
# The modules are committed, so that the Idris build needs no other step
# and a change of upstream's ODS, or of what the specification admits,
# shows as a change of the Idris it means. A module carries no stamp of
# what it was generated from: `check` writes each again with the generator
# the build made and compares it with the committed file, so a stale
# module and one edited by hand both differ, and `make build` writes
# either again. So `check` runs where the generator is built (make
# test-mlir-tools).
root=$(cd "$(dirname "$0")/.." && pwd)
. "$root/tools/toolchain.sh"
src=$root/compiler/src/IdrisMLIR
# The include directory the admitted record files resolve their own
# include of idr/IR/Generated/IdrAdmittedBase.td against, and the files.
idr_include=$root/foreign/idr/include
admitted=$idr_include/idr/IR/Generated

usage() {
  echo "usage: tools/dialects.sh generate|check [typecheck]" >&2
  exit 2
}
[ $# -eq 1 ] || [ $# -eq 2 ] || usage
case $1 in generate | check) ;; *) usage ;; esac
# The include directories of MLIR's ODS (mlir_include), of LLVM's
# (llvm_include) and of the ODS MLIR's build generates (generated_include:
# Linalg's named ops, written from their YAML): one installed tree in
# stage 2's prefix, which holds all three; in the typecheck build's, the
# source tree's two and that build's own, since the source tree has no
# generated file.
case ${2-} in
  '')
    mlir_include=${llvm_bin%/bin}/include
    llvm_include=$mlir_include
    generated_include=$mlir_include
    step='make build'
    ;;
  typecheck)
    typecheck_tree=$(stamp_field "$typecheck_toolchain" tree)
    typecheck_build=$(stamp_field "$typecheck_toolchain" llvm_build)
    if [ -z "$typecheck_tree" ] || [ -z "$typecheck_build" ]; then
      echo "tools/dialects.sh: no typecheck build; run: tools/bootstrap.sh typecheck" >&2
      exit 1
    fi
    mlir_include=$typecheck_tree/mlir/include
    llvm_include=$typecheck_tree/llvm/include
    generated_include=$typecheck_build/tools/mlir/include
    idris_mlir_tblgen=$typecheck_tblgen
    step='make typecheck-tblgen'
    ;;
  *) usage ;;
esac
# Without the generator no module is written, so say which step builds it.
if [ ! -x "$idris_mlir_tblgen" ]; then
  echo "tools/dialects.sh: $idris_mlir_tblgen is missing; $step builds it" >&2
  exit 1
fi

# The upstream dialects the frontend writes, as the specification lists
# them in one of its committed outputs: per line the dialect's namespace,
# its name in the specification, which names its admitted record file
# (IdrAdmitted<Name>.td) and its modules, and its entries file beside it,
# or `-` for a dialect whose types and attributes the bytecode writer
# writes only as text; `#` begins a comment. The file of a dialect's ops is
# the specification's, which its admitted record file includes, and so is
# the file of its bytecode records, which its entries file includes.
written=$admitted/WrittenDialects.txt
if [ ! -f "$written" ]; then
  echo "tools/dialects.sh: $written is missing; the dialect's specification writes it" >&2
  exit 1
fi
dialects() {
  awk -v admitted="$admitted" '/^#/ || NF == 0 { next }
    { print $1, $2, ($3 == "-" ? "-" : admitted "/" $3) }' "$written"
}

work=$(mktemp -d "${TMPDIR:-/tmp}/idris-mlir-dialects.XXXXXX") || exit 1
trap 'rm -rf "$work"' EXIT

# Each dialect's modules, as generator:directory: its syntax, its ops, which
# import the syntax, and its entries.
modules="syntax:Syntax dialect:Dialect bytecode:Encoding"

# The modules, one per line: the generator, the directory, the
# dialect, the module's name and the file it is generated from, which is
# the dialect's entries file for its entries and its admitted record file
# for the others. A dialect without an entries file has no entries.
dialects | while read -r name module bytecode; do
  for pair in $modules; do
    case ${pair%%:*} in
      bytecode) source=$bytecode ;;
      *) source=$admitted/IdrAdmitted$module.td ;;
    esac
    [ "$source" = - ] || echo "${pair%%:*} ${pair#*:} $name $module $source"
  done
done > "$work/modules"

status=0
while read -r generator directory name module source; do
  path=$src/$directory/$module.idr
  out=$work/$directory-$module.idr
  "$idris_mlir_tblgen" "-gen-idris-$generator" "-idris-dialect=$name" \
    "-idris-module=IdrisMLIR.$directory.$module" \
    "-idris-syntax-module=IdrisMLIR.Syntax.$module" -I "$mlir_include" -I "$llvm_include" \
    -I "$generated_include" -I "$idr_include" "$source" -o "$out" || exit 1
  if cmp -s "$out" "$path"; then
    [ "$1" = check ] && echo "IdrisMLIR.$directory.$module: current"
  elif [ "$1" = generate ]; then
    mkdir -p "$src/$directory"
    mv "$out" "$path" || exit 1
    echo "tools/dialects.sh: wrote IdrisMLIR.$directory.$module"
  elif [ -f "$path" ]; then
    echo "IdrisMLIR.$directory.$module: not what the generator writes (make build writes it again)"
    status=1
  else
    echo "IdrisMLIR.$directory.$module: missing (make build writes it)"
    status=1
  fi
done < "$work/modules"

# No module of a directory is left from a dialect the specification no
# longer lists, or from a bytecode file it dropped. A module the
# specification writes is the manifest's, which says so by naming its
# path.
manifest=$root/foreign/idr/generated.manifest
for pair in $modules; do
  directory=${pair#*:}
  for path in "$src/$directory"/*.idr; do
    [ -f "$path" ] || continue
    module=${path##*/}
    module=${module%.idr}
    if awk -v p="${path#"$root"/}" '$2 == p { found = 1 } END { exit !found }' "$manifest" 2> /dev/null; then
      continue
    fi
    if ! awk -v d="$directory" -v m="$module" '$2 == d && $4 == m { found = 1 } END { exit !found }' "$work/modules"; then
      echo "IdrisMLIR.$directory.$module: of no dialect the specification lists"
      status=1
    fi
  done
done
exit "$status"
